vector<I>response(const vector<E>&w,int n,int v){vector<I>r(size_t(n+1)*v);for(int k=0;k<v;k++)r[size_t(v+k)*v+k]=1;for(auto it=w.rbegin();it!=w.rend();++it){auto[op,a,b,c,f,z]=*it;if(op==1){for(int k=0;k<v;k++){__int128 q=(__int128)r[size_t(b)*v+k]+(__int128)c*r[size_t(a)*v+k];if(q<INT64_MIN||q>INT64_MAX)throw runtime_error("overflow");r[size_t(b)*v+k]=(I)q;}}if(op==3)fill(r.begin()+size_t(n)*v,r.end(),0);if(op==2){for(int k=0;k<v;k++){__int128 q=(__int128)r[size_t(a)*v+k]+r[size_t(n)*v+k];if(q<INT64_MIN||q>INT64_MAX)throw runtime_error("COPYoverflow");r[size_t(a)*v+k]=(I)q;}fill(r.begin()+size_t(n)*v,r.end(),0);}}return r;}
